// Fim dos Tempos · Arco 2 · Lendas Urbanas e Linhas Narrativas · gerado por a2-lendas-linhas.js
const DADOS = {"linha":[{"t":"Chegada de Ghorskander e Lakshrimi à cidade.","antes":true},{"t":"Ghorskander transfere a consciência de Lakshrimi para um golem, e ela se esconde num espaço entre as dimensões.","antes":true,"av":"Aventura 6"},{"t":"Os Avatares do Futuro Eterno começam a recrutar nobres.","antes":true},{"t":"Primeiros assassinatos no Baile da Primavera; a Duquesa Alfraye cancela os próximos bailes.","antes":true,"av":"Aventura 6"},{"t":"Ghorskander ensina Khenzarr.","antes":true,"av":"Aventura 5"},{"t":"Algumas famílias nobres deixam Valkaria.","antes":true},{"t":"Madame Margebell aprende técnicas de pintura de doutrinação.","antes":true,"av":"Aventura 1"},{"t":"Ghorskander opera Tryphne e lhe ensina a operar outros prisioneiros.","antes":true,"av":"Aventura 3"},{"t":"Aldanna é \"educada\" por Madame Margebell e deixa seu grupo de aventureiros.","antes":true,"av":"Aventura 1"},{"t":"Os dragões do esgoto começam a fazer vítimas na Baixa Vila de Lena.","antes":true,"av":"Aventura 5"},{"t":"Ghorskander instala Imagodutos em vários pontos de Valkaria.","antes":true,"av":"Aventuras 4 e 5"},{"t":"Calliko é internado na Casa de Repouso Millicent.","antes":true,"av":"Aventura 4"},{"t":"Chegada dos personagens jogadores a Valkaria.","antes":true,"av":"Aventura 0"},{"t":"A violência em Valkaria aumenta cada vez mais.","av":"Lei & Ordem"},{"t":"Aventureiros começam a se ver incapazes de usar seus poderes e capacidades especiais.","av":"Aventura 1"},{"t":"As mortes na Baixa Vila de Lena aumentam.","av":"Aventura 5"},{"t":"Vladmir Mors é preso pelos crimes e vai parar na Rocha Cinzenta.","av":"Aventura 5"},{"t":"A Rocha Cinzenta é quase toda dominada pela Companhia dos Irmãos e vira uma fortaleza onde os criminosos recebem implantes de cristal rosado para manter poderes e habilidades.","av":"Aventura 3"},{"t":"Brigas gigantescas e cada vez mais violentas forçam a Terceira Opção a fechar as portas.","av":"Aventura 4"},{"t":"As partituras de Calliko continuam circulando, agora pela cidade inteira.","av":"Aventura 4"},{"t":"Paollus executa um membro da Casa Blasanov, uma irmandade rival, e provoca uma guerra de irmandades. As mortes de criminosos e inocentes chegam às centenas.","av":"Mini-Aventura 2 (Irmandade Máxima); com a Aventura 1 resolvida, há heróis para evitar o massacre"},{"t":"A Xerife Mathilda Nolt tenta intervir na guerra criminosa.","av":"Mini-Aventura 2"},{"t":"Uma retaliação da Companhia dos Irmãos destrói a Guarita da Praia e mata a maior parte dos detetives. A reforma da Guarda parece um fracasso total.","av":"Mini-Aventura 2; a Aventura 1 resolvida evita a destruição da Guarita"},{"t":"Aventureiros tentam tomar a lei nas próprias mãos, mas se veem indefesos frente a criminosos e até a turbas de plebeus furiosos.","av":"Aventura 1"},{"t":"A nobreza exige uma intervenção de Shivara. O Exército do Reinado toma as ruas, e logo começam excessos e explosões de violência dos \"pacificadores\"."},{"t":"Pressionada, a Academia Arcana envia representantes para defender a população, mas eles não conseguem usar magia em Valkaria. Vários morrem.","av":"Aventura 1"},{"t":"Valkaria é tomada por uma guerra urbana de todos contra todos: irmandades, Exército, aventureiros, cidadãos e guardas. Alguns heróis famosos tentam intervir e são mortos."},{"t":"O mecano-lagarto-terror se materializa na capital e pisoteia as ruas. Ninguém é capaz de detê-lo. Shivara intervém pessoalmente, é derrotada e quase morre.","av":"Aventura 7"},{"t":"Depois de espalhar destruição, o mecano-lagarto-terror deixa Valkaria e desaparece nas planícies de Deheon. A reconstrução será longa e custosa; talvez a cidade nunca mais seja a mesma.","av":"Aventura 7"},{"t":"A maior parte da nobreza perde a confiança em Shivara e no Reinado, abandona a capital e se junta ao Dr. Vesper, que, com recursos praticamente ilimitados e o apoio de muitas das pessoas mais influentes do mundo, põe seu plano em prática com tranquilidade.","av":"Aventuras 6 e 7"}]};
(async function macroLinha(D) {
		const ESTADO = "fdtLendas";
		const est = foundry.utils.deepClone(game.user.getFlag("world", ESTADO) ?? {});
		est.linha ??= D.linha.map((e) => !!e.antes);
		est.evitados ??= [];
		const prox = est.linha.findIndex((f, i) => !f && !est.evitados.includes(i));
		const op = D.linha.map((e, i) => `<option value="${i}"${i === prox ? " selected" : ""}>${i + 1}. ${est.linha[i] ? "✔️ " : est.evitados.includes(i) ? "🚫 " : ""}${e.t.slice(0, 70)}${e.t.length > 70 ? "..." : ""}</option>`).join("");
		const res = await foundry.applications.api.DialogV2.prompt({
			window: { title: "Valkaria · Linha do Tempo" },
			position: { width: 600 },
			content: `
				<p>Valkaria sem a intervenção dos heróis. Não há momento fixo: descreva o estado da cidade de acordo com o que o grupo não resolveu (na mesa original, o arco durou 6 meses).</p>
				<div class="form-group"><label>O que fazer</label><select name="acao">
					<option value="acontece">O acontecimento escolhido acontece</option>
					<option value="evitado">O grupo evitou o acontecimento escolhido</option>
					<option value="desfazer">Desmarcar o acontecimento escolhido</option>
					<option value="ver">Ver a linha do tempo</option>
					<option value="zerar">Recomeçar (só o que já aconteceu antes da chegada)</option></select></div>
				<div class="form-group"><label>Acontecimento</label><select name="i">${op}</select></div>`,
			ok: { label: "Aplicar", callback: (ev, button) => Object.fromEntries(new FormData(button.form)) }
		});
		if (!res) return;
		const whisper = ChatMessage.getWhisperRecipients("GM");
		const i = Number(res.i) || 0;
		const e = D.linha[i];
		let html = "";
		if (res.acao === "zerar") {
			est.linha = D.linha.map((x) => !!x.antes);
			est.evitados = [];
			html = "<p>Linha do tempo recomeçada.</p>";
		} else if (res.acao === "acontece" && e) {
			est.linha[i] = true;
			est.evitados = est.evitados.filter((x) => x !== i);
			await ChatMessage.create({ content: `<h3>Valkaria</h3><p>${e.t}</p>` });
			html = `<p>Marcado como acontecido: ${i + 1}.${e.av ? ` Ligado a: ${e.av}.` : ""}</p>`;
		} else if (res.acao === "evitado" && e) {
			est.linha[i] = false;
			if (!est.evitados.includes(i)) est.evitados.push(i);
			html = `<p>Evitado pelo grupo: ${e.t}</p>`;
		} else if (res.acao === "desfazer" && e) {
			est.linha[i] = false;
			est.evitados = est.evitados.filter((x) => x !== i);
			html = `<p>Desmarcado: ${i + 1}.</p>`;
		}
		const linhas = D.linha.map((x, j) => `<li>${est.linha[j] ? "✔️" : est.evitados.includes(j) ? "🚫" : "·"} ${x.t}${x.av ? ` <i>(${x.av})</i>` : ""}</li>`);
		const seguinte = D.linha.findIndex((x, j) => !est.linha[j] && !est.evitados.includes(j));
		html += res.acao === "ver" || res.acao === "zerar"
			? `<h3>Linha do tempo sem os heróis</h3><ol style="padding-left:1.2em;list-style:none">${linhas.join("")}</ol>`
			: seguinte >= 0 ? `<p><b>Próximo:</b> ${D.linha[seguinte].t}</p>` : "<p>Não há mais acontecimentos.</p>";
		await game.user.setFlag("world", ESTADO, est);
		await ChatMessage.create({ whisper, content: html });
	})(DADOS);
